// sync-cards.js
//
// data/cards.json is the source of truth for card data. src/data/cards.js
// is a generated copy (as an ES module, since the app imports it directly)
// for the engine/app to consume. Copying only ever goes one way: this
// script reads data/cards.json and overwrites src/data/cards.js. Never
// hand-edit src/data/cards.js — edit data/cards.json and re-run this.
//
// It also mirrors data/card-fidelity.json (generated by
// scripts/build-coverage.cjs) to src/data/card-fidelity.js so the package's
// "./data" export can surface CARD_FIDELITY to downstream consumers.

const fs = require('node:fs');
const path = require('node:path');

const DATA_DIR = path.join(__dirname, '..', 'data');
const OUT_DIR = path.join(__dirname, '..', 'src', 'data');

const cards = JSON.parse(fs.readFileSync(path.join(DATA_DIR, 'cards.json'), 'utf8'));
fs.writeFileSync(
  path.join(OUT_DIR, 'cards.js'),
  `export default ${JSON.stringify(cards, null, 2)}\n`
);
console.log(`Synced ${cards.length} cards from data/cards.json -> src/data/cards.js`);

const fidelityPath = path.join(DATA_DIR, 'card-fidelity.json');
if (fs.existsSync(fidelityPath)) {
  const fidelity = JSON.parse(fs.readFileSync(fidelityPath, 'utf8'));
  fs.writeFileSync(
    path.join(OUT_DIR, 'card-fidelity.js'),
    `export default ${JSON.stringify(fidelity, null, 2)}\n`
  );
  console.log(
    `Synced fidelity (${Object.keys(fidelity.fidelity).length} cards) -> src/data/card-fidelity.js`
  );
}
